// QuasarApp Group - Devlog page controller (issue #75)
//
// Progressive enhancements on top of the static markup generated by
// scripts/build-devlog.js:
//
// - list page (/devlog): project-tag filtering. The static markup shows
//   every post (newest first); the filter buttons hide items that do not
//   carry the selected tag. ?tag={slug} deep links pre-select a project
//   (the Ecliptica hub links to /devlog/?tag=ecliptica) and changing the
//   filter rewrites the query string, so any view is shareable.
//
// - post pages (/devlog/{slug}): non-blocking local video loading. A
//   <video class="devlog-video-el"> ships with a static poster and no
//   source (preload="none"); an IntersectionObserver attaches the real
//   source shortly before the video scrolls into view. Visitors with
//   prefers-reduced-motion get the source attached immediately (no
//   deferred media swap) and the poster stays the static fallback until
//   they start playback. Without IntersectionObserver the sources are
//   attached immediately so the videos keep working.
//
// Loads after js/i18n.js and js/main.js, on the devlog pages only.
(function () {
    'use strict';

    /** Attach the deferred source of one local <video> element. */
    function attachVideoSource(video) {
        const src = video.getAttribute('data-src');
        if (!src) return;
        video.removeAttribute('data-src');
        const source = document.createElement('source');
        source.src = src;
        video.appendChild(source);
        video.load();
    }

    function initVideoLazyLoad() {
        const videos = Array.from(document.querySelectorAll('video.devlog-video-el[data-src]'));
        if (videos.length === 0) return;

        const prefersReducedMotion = window.matchMedia &&
            window.matchMedia('(prefers-reduced-motion: reduce)').matches;

        // Reduced motion (or no IntersectionObserver): attach the sources
        // right away - nothing plays by itself, the poster stays the
        // static fallback until the visitor starts playback.
        if (prefersReducedMotion || typeof IntersectionObserver === 'undefined') {
            videos.forEach(attachVideoSource);
            return;
        }

        // Standard path: attach the source when the video nears the
        // viewport, so a full post never downloads video data it may
        // never show.
        const observer = new IntersectionObserver(function (entries) {
            entries.forEach(function (entry) {
                if (!entry.isIntersecting) return;
                attachVideoSource(entry.target);
                observer.unobserve(entry.target);
            });
        }, { rootMargin: '600px 0px' });
        videos.forEach(function (video) { observer.observe(video); });
    }

    function initListFilter() {
        const buttons = Array.from(document.querySelectorAll('.devlog-filter-btn'));
        const items = Array.from(document.querySelectorAll('#devlog-list .devlog-item'));
        const noResults = document.querySelector('.devlog-no-results');
        if (buttons.length === 0 || items.length === 0) return;

        function tagFromUrl() {
            const tag = new URLSearchParams(window.location.search).get('tag');
            return tag && buttons.some((b) => b.dataset.filter === tag) ? tag : 'all';
        }

        function applyFilter(tag, updateUrl) {
            buttons.forEach(function (btn) {
                btn.classList.toggle('active', btn.dataset.filter === tag);
                btn.setAttribute('aria-pressed', String(btn.dataset.filter === tag));
            });
            let visible = 0;
            items.forEach(function (item) {
                const tags = (item.dataset.tags || '').split(',').map((t) => t.trim()).filter(Boolean);
                const show = tag === 'all' || tags.indexOf(tag) !== -1;
                item.hidden = !show;
                if (show) visible += 1;
            });
            if (noResults) noResults.hidden = visible > 0;
            if (updateUrl && typeof history.replaceState === 'function') {
                const url = new URL(window.location.href);
                if (tag === 'all') {
                    url.searchParams.delete('tag');
                } else {
                    url.searchParams.set('tag', tag);
                }
                history.replaceState(null, '', url);
            }
        }

        buttons.forEach(function (btn) {
            btn.addEventListener('click', function () {
                applyFilter(btn.dataset.filter, true);
            });
        });

        // Deep link (?tag=ecliptica) and back/forward navigation.
        window.addEventListener('popstate', function () {
            applyFilter(tagFromUrl(), false);
        });
        applyFilter(tagFromUrl(), false);
    }

    document.addEventListener('DOMContentLoaded', function () {
        initVideoLazyLoad();
        if (document.body.getAttribute('data-devlog-page') === 'list') {
            initListFilter();
        }
    });
})();
